// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != c.owner());
        address originalOwner = c.owner();
        vm.prank(caller);
        bool ok = true;
        try c.transferOwnership(newOwner) {} catch { ok = false; }
        assertTrue(ok == false || c.owner() == originalOwner);
    }
}
